=== PR ===
Title: Add audit logging to billing routes and require billing:read scope

Description:
Two related changes in `src/routes/billing.ts`, both requested in SEC-142:

1. Every billing request is now logged through `auditLog` (user id, route, status).
2. The GET routes now require the `billing:read` OAuth scope instead of just a valid session. The web and mobile clients already request this scope, so no client change is needed.

=== diff ===
diff --git a/src/routes/billing.ts b/src/routes/billing.ts
--- a/src/routes/billing.ts
+++ b/src/routes/billing.ts
@@ -1,18 +1,20 @@
 import { Router } from "express";
-import { requireSession } from "../middleware/auth";
+import { requireSession, requireScope } from "../middleware/auth";
+import { auditLog } from "../middleware/audit";
 import { getInvoices, getPaymentMethods } from "../services/billing";

 export const billingRouter = Router();

 billingRouter.use(requireSession);
+billingRouter.use(auditLog("billing"));

-billingRouter.get("/invoices", async (req, res) => {
+billingRouter.get("/invoices", requireScope("billing:read"), async (req, res) => {
   const invoices = await getInvoices(req.user.accountId);
   res.json({ invoices });
 });

-billingRouter.get("/payment-methods", async (req, res) => {
+billingRouter.get("/payment-methods", requireScope("billing:read"), async (req, res) => {
   const methods = await getPaymentMethods(req.user.accountId);
   res.json({ methods });
 });

