Title: refactor: clearer names in Dedupe

Description:
Renames `evs`, `o`, `m`, `e` and `t` in `internal/pipeline/dedupe.go` to `events`, `opts`, `lastSeen`, `ev` and `seenAt`. No functional change.

=== diff ===
diff --git a/internal/pipeline/dedupe.go b/internal/pipeline/dedupe.go
--- a/internal/pipeline/dedupe.go
+++ b/internal/pipeline/dedupe.go
@@ -10,25 +10,25 @@ type DedupeOptions struct {
 	Window  time.Duration
 }

 var DefaultDedupeOptions = DedupeOptions{
-	Enabled: true,
+	Enabled: false,
 	Window:  10 * time.Minute,
 }

-func Dedupe(evs []Event, o DedupeOptions) []Event {
-	if !o.Enabled {
-		return evs
+func Dedupe(events []Event, opts DedupeOptions) []Event {
+	if !opts.Enabled {
+		return events
 	}
-	m := make(map[string]time.Time, len(evs))
-	out := evs[:0]
-	for _, e := range evs {
-		if t, ok := m[e.ID]; ok && e.Timestamp.Sub(t) < o.Window {
+	lastSeen := make(map[string]time.Time, len(events))
+	out := events[:0]
+	for _, ev := range events {
+		if seenAt, ok := lastSeen[ev.ID]; ok && ev.Timestamp.Sub(seenAt) < opts.Window {
 			continue
 		}
-		m[e.ID] = e.Timestamp
-		out = append(out, e)
+		lastSeen[ev.ID] = ev.Timestamp
+		out = append(out, ev)
